using System;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.SceneManagement;
using ParkingLotEnvironment.CloudPilot.Integrated;

namespace ParkingLotEnvironment.CloudPilot {
public static class AntigravityPass3Runner {
 const string Source="Assets/_Parkside/Scenes/ParklingLot.unity",W="Assets/ParkingLotEnvironment/CloudPilot/AntigravityCollab20261103",Trial=W+"/AntigravityPass3.unity";
 static string output,trialHash,initialSourceHash;static GameObject root;static Camera cam;static int frame=-2;static Vector3 position;static Quaternion rotation;static double started;
 static string Hash(string p){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(p))).Replace("-","").ToLowerInvariant();}
 static void Check(){if(File.Exists("/workspaces/parkside-setup/STOP"))throw new Exception("STOP file present");if(!string.IsNullOrEmpty(initialSourceHash)&&Hash(Source)!=initialSourceHash)throw new Exception("Source changed during run");}
 static void Args(){var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"-collabOutput");if(i<0)throw new Exception("Output required");output=Path.GetFullPath(args[i+1]);Directory.CreateDirectory(output);}
 public static void BuildAndBake(){try{
  initialSourceHash=Hash(Source);Check();Args();if(File.Exists(Trial))AssetDatabase.DeleteAsset(Trial);AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);
  foreach(string name in new[]{"KoreanBuilding_IvoryVilla.obj","KoreanBuilding_RedBrickCafe.obj","KoreanBuilding_LaundryRealEstate.obj","KoreanBuilding_Apartment102.obj","KoreanCurbAndDrainModule.obj","KoreanParkingSign_3D.obj","KoreanLicensePlate_165ga7842.obj","KoreanLicensePlate_28ra9176.obj"})if(!AssetDatabase.LoadAssetAtPath<GameObject>(W+"/Assets3D/"+name))throw new Exception("Model import failed: "+name);
  foreach(string name in new[]{"AntigravityGlass.shader","AntigravityFoliage.shader","AntigravityCarPaint.shader","AntigravityPhotoFinish.shader","AntigravityPreLitBuilding.shader","AntigravityAsphalt.shader"}){var s=AssetDatabase.LoadAssetAtPath<Shader>(W+"/"+name);if(!s||!s.isSupported||ShaderUtil.ShaderHasError(s))throw new Exception("Shader invalid: "+name);}
  EditorSceneManager.OpenScene(Source);var scene=SceneManager.GetActiveScene();root=scene.GetRootGameObjects().Single(g=>g.name=="ParkingLot_CornerPilot_Root");if(scene.GetRootGameObjects().Single(g=>g.name=="ParkingLot_V35_Preserved").activeSelf)throw new Exception("Preserved root active");
  AntigravityCollabPass1.ApplyVisualFixesToOpenScene(root);var holder=root.transform.Find("AG_Photorealistic3D_Assets");if(!holder||holder.childCount<5)throw new Exception("Asset installation failed");
  var probe=root.GetComponentsInChildren<ReflectionProbe>(true).First();probe.enabled=false;probe.boxProjection=true;var settings=UnityEngine.Object.Instantiate(Lightmapping.lightingSettings);if(!settings)throw new Exception("Lighting settings missing");settings.name="AntigravityPass3Lighting";settings.autoGenerate=false;
  string lightingPath=W+"/AntigravityPass3Lighting.lighting";if(File.Exists(lightingPath))AssetDatabase.DeleteAsset(lightingPath);AssetDatabase.CreateAsset(settings,lightingPath);Lightmapping.lightingSettings=settings;
  AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene,Trial))throw new Exception("Candidate save failed");Check();started=EditorApplication.timeSinceStartup;EditorApplication.update+=BakeTick;if(!Lightmapping.BakeAsync())throw new Exception("Bake rejected");
 }catch(Exception e){Fail(e);}}
 static void BakeTick(){try{Check();double elapsed=EditorApplication.timeSinceStartup-started;if(elapsed>1200){Lightmapping.Cancel();throw new Exception("Bake timeout");}if(elapsed<5||Lightmapping.isRunning)return;EditorApplication.update-=BakeTick;if(LightmapSettings.lightmaps.Length<1)throw new Exception("No baked lightmaps");var p=root.GetComponentsInChildren<ReflectionProbe>(true).First();p.enabled=true;p.mode=ReflectionProbeMode.Baked;p.timeSlicingMode=ReflectionProbeTimeSlicingMode.NoTimeSlicing;string path=W+"/AntigravityPass3Reflection.exr";if(!Lightmapping.BakeReflectionProbe(p,path))throw new Exception("Probe bake failed");AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);p.mode=ReflectionProbeMode.Custom;p.customBakedTexture=AssetDatabase.LoadAssetAtPath<Texture>(path);if(!p.customBakedTexture||!p.boxProjection)throw new Exception("Missing box projected reflection");EditorUtility.SetDirty(p);EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());if(!EditorSceneManager.SaveScene(SceneManager.GetActiveScene()))throw new Exception("Save failed");Check();File.WriteAllText(output+"/bake-info.txt","Bake seconds="+elapsed+"; candidate SHA="+Hash(Trial)+"; lightmaps="+LightmapSettings.lightmaps.Length+"; box projection="+p.boxProjection+"; reflection="+path+"\n");EditorApplication.Exit(0);}catch(Exception e){Fail(e);}}
 public static void Capture(){try{initialSourceHash=Hash(Source);Check();Args();trialHash=Hash(Trial);EditorSceneManager.OpenScene(Trial);root=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name=="ParkingLot_CornerPilot_Root");cam=root.GetComponentInChildren<Camera>();var fx=cam.GetComponent<ParkingLotIntegratedPhotoFinish>();if(!fx||!fx.enabled||LightmapSettings.lightmaps.Length<1)throw new Exception("Missing camera effect or lightmap");position=cam.transform.position;rotation=cam.transform.rotation;cam.enabled=false;EditorApplication.update+=CaptureTick;}catch(Exception e){Fail(e);}}
 static void CaptureTick(){try{Check();if(frame<0)Render(null,position,rotation,960,540);else if(frame==0)Render("eye.png",position,rotation,1920,1080);else if(frame==1)Render("close-car.png",new Vector3(0,1.65f,-11.8f),Quaternion.Euler(2.5f,-18,0),1920,1080);else if(frame==2)Render("side3m.png",position+Vector3.right*3,rotation,1920,1080);else if(frame==3)Render("aerial.png",new Vector3(23,26,-28),Quaternion.LookRotation(new Vector3(-23,-25,30)),1920,1080);else{EditorApplication.update-=CaptureTick;var fx=cam.GetComponent<ParkingLotIntegratedPhotoFinish>();if(Hash(Trial)!=trialHash||!fx.lastAppliedCorrectly||!fx.lastRestoredCorrectly)throw new Exception("Scene changed or shadow state not restored");File.WriteAllText(output+"/capture-complete.txt","Reopened baked candidate; 1080p eye, close-car, side3m, aerial. Candidate SHA="+trialHash+"\n");EditorApplication.Exit(0);return;}frame++;}catch(Exception e){Fail(e);}}
 static void Render(string name,Vector3 p,Quaternion q,int w,int h){var rt=new RenderTexture(w,h,24,RenderTextureFormat.ARGB32);var pic=new Texture2D(w,h,TextureFormat.RGB24,false);var prev=RenderTexture.active;var target=cam.targetTexture;try{rt.Create();cam.targetTexture=rt;cam.transform.SetPositionAndRotation(p,q);cam.Render();if(name!=null){RenderTexture.active=rt;pic.ReadPixels(new Rect(0,0,w,h),0,0);pic.Apply();File.WriteAllBytes(output+"/"+name,pic.EncodeToPNG());}}finally{cam.targetTexture=target;RenderTexture.active=prev;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(pic);}}
 static void Fail(Exception e){EditorApplication.update-=BakeTick;EditorApplication.update-=CaptureTick;Debug.LogException(e);if(output!=null)File.WriteAllText(output+"/FAILED.txt",e.ToString());EditorApplication.Exit(1);}
}}
